INSERT INTO part SELECT * REPLACE (p_partkey + 3000000000 AS p_partkey) FROM part WHERE p_partkey IN (SELECT l_partkey FROM lineitem WHERE l_orderkey < 2147483648 AND l_orderkey % 8 = 0) AND NOT EXISTS (SELECT 1 FROM part AS c WHERE c.p_partkey = part.p_partkey + 3000000000);
INSERT INTO lineitem SELECT * REPLACE (l_orderkey + 3000000000 AS l_orderkey, l_partkey + 3000000000 AS l_partkey, l_suppkey + 3000000000 AS l_suppkey, l_extendedprice / (1 + (l_partkey + l_suppkey) % 5) AS l_extendedprice) FROM lineitem WHERE l_orderkey < 2147483648 AND l_orderkey % 8 = 0 AND NOT EXISTS (SELECT 1 FROM lineitem AS c WHERE c.l_orderkey = lineitem.l_orderkey + 3000000000 AND c.l_linenumber = lineitem.l_linenumber);
